onKeyDown={(event) => {
      if (event.nativeEvent.isComposing) return;
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        const options = modelListRef.current?.querySelectorAll<HTMLButtonElement>('button[role="option"]');
        if (options?.length) { event.preventDefault(); options[event.key === "ArrowDown" ? 0 : options.length - 1]?.focus(); }
      }
      if (event.key === "Enter") {
        const match = models.find((item) => item.id.toLowerCase() === query.toLowerCase());
        if (match || (manualValid && !exactMatch)) { event.preventDefault(); chooseModel(match?.id ?? query); }
      }
    }}
